<div class="card"><div class="card-header"><h3 class="card-title">Parcelas encaminhadas à CMDF</h3></div><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Documento / Parcela</th><th>Fornecedor</th><th>Empenho</th><th>Valor</th><th>Liquidação</th><th style="min-width:560px">CMDF</th></tr></thead><tbody><?php foreach($itens as $i):?><tr><td><a href="/documentos/<?=e($i['documento_id'])?>"><strong><?=e($i['tipo_documento'])?> <?=e($i['documento_numero'])?></strong></a><div class="small">Parcela <?=e($i['numero_parcela'])?></div></td><td><?=e($i['fornecedor'])?></td><td><?=e($i['empenho_numero'])?>/<?=e($i['empenho_ano'])?></td><td><?=money($i['valor_total'])?></td><td><?=e($i['data_liquidacao'])?></td><td><?php if($i['status']!=='CONCLUIDA'):?><form method="post" action="/documentos/<?=e($i['documento_id'])?>/parcelas/<?=e($i['parcela_id'])?>/cmdf" class="row g-1"><div class="col"><label class="form-label small mb-0">Envio SEINFRA</label><input type="date" name="data_envio_seinfra" class="form-control form-control-sm"></div><div class="col"><label class="form-label small mb-0">Despacho SEINFRA</label><input type="date" name="data_despacho_seinfra" class="form-control form-control-sm"></div><div class="col"><label class="form-label small mb-0">Envio Economia</label><input type="date" name="data_envio_economia" class="form-control form-control-sm"></div><div class="col"><label class="form-label small mb-0">Atendimento Economia</label><input type="date" name="data_atendimento_economia" class="form-control form-control-sm"></div><div class="col"><label class="form-label small mb-0">Conclusão</label><input type="date" name="data_conclusao" value="<?=date('Y-m-d')?>" class="form-control form-control-sm" required></div><div class="col-12 mt-1"><div class="input-group input-group-sm"><input name="observacoes" class="form-control" placeholder="Observações da CMDF"><button class="btn btn-dark">Concluir CMDF</button></div></div></form><?php else:?><span class="badge text-bg-success">CONCLUÍDA</span><div class="small mt-1"><?=e($i['data_conclusao'])?></div><?php endif;?></td></tr><?php endforeach;?><?php if(!$itens):?><tr><td colspan="6" class="text-center text-body-secondary py-4">Fila CMDF vazia.</td></tr><?php endif;?></tbody></table></div></div>